   200→
   201→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   202→    var inp = document.getElementById(wid + "-inp");
   203→    var btn = document.getElementById(wid + "-btn");
   204→    var res = document.getElementById(wid + "-res");
   205→    var btnLabel = cfg.buttonText;
