   235→          } else {
   236→            var html = '<div class="zcc-result fail">' + esc(data.message);
   237→            if (cfg.showWaitlistOnFailure) {
   238→              html +=
   239→                '<div class="zcc-wl">' +
   240→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
