   271→  }
   272→
   273→  function joinWaitlist(zip, email, wBtn) {
   274→    wBtn.disabled = true;
   275→    wBtn.textContent = "Joining\u2026";
   276→
   277→    fetch(API_BASE + "/api/waitlist", {
   278→      method: "POST",
   279→      headers: { "Content-Type": "application/json" },
   280→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
   281→    })
   282→      .then(function (r) { return r.json(); })
   283→      .then(function (data) {
   284→        var wlEl = wBtn.closest(".zcc-wl");
